import manifest from "./media-manifest.json";

// Client photos/videos live on Vercel Blob. The manifest is generated by
// scripts/upload-media.mjs (see README "Media"); anything the admin replaces or
// adds is layered on top as an override (see lib/content.ts).
export type Media = { url: string; w: number; h: number };
export type MediaOverride = Media | { hidden: true };

export const MANIFEST = manifest as Record<string, Media>;

const isHidden = (o?: MediaOverride): o is { hidden: true } => !!o && "hidden" in o;

export function buildMedia(overrides: Record<string, MediaOverride> = {}) {
  const resolve = (key: string): Media | undefined => {
    const o = overrides[key];
    return o && !isHidden(o) ? o : MANIFEST[key];
  };
  /** Always resolves, even for hidden keys, so fixed slots never crash a page. */
  const media = (key: string): Media => {
    const m = resolve(key);
    if (!m) throw new Error(`Missing media "${key}". Run npm run media:upload.`);
    return m;
  };
  /** False when the admin removed it. */
  const visible = (key: string) => !isHidden(overrides[key]) && !!resolve(key);
  /** Video plus the poster frame generated next to it (foo.mp4 + foo.jpg). */
  const video = (base: string) => ({ src: media(`${base}.mp4`), poster: media(`${base}.jpg`) });
  /** Every visible item in a folder, including ones the admin added. */
  const keysIn = (folder: string) =>
    [...new Set([...Object.keys(MANIFEST), ...Object.keys(overrides)])]
      .filter((k) => k.startsWith(`${folder}/`) && visible(k))
      .sort();
  const mediaIn = (folder: string) => keysIn(folder).map(media);
  return { media, visible, video, keysIn, mediaIn };
}
export type MediaApi = ReturnType<typeof buildMedia>;
